// Room "P4 bath and store" (interior designer's part): a 3 x 2 bath and linen store, box [69,6,19,71,8,20].
// Focal piece: the cauldron (the bath) in the far south-west corner, out of the entry's line of sight. Two barrels hold
// the linen and each carries a standing lantern on its lid, so the corners where the furniture sits are lit at feet
// level. The lane from the door runs (71,19) -> (70,19) -> (70,20), clear at y6..7 to the cauldron and both barrels.
import { B, layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  const barrel = ["barrel", { facing: "up", open: "false" }];
  const lantern = B.lantern(false);
  // y6: the barrels (x69 z19, x71 z20) and the cauldron (x69 z20); x70 is the lane
  layers(g, [69, 6, 19], { B: barrel, K: "cauldron" }, [
    ["B  ",
     "K B"],
  ]);
  // y7: a lantern standing on each barrel lid
  layers(g, [69, 7, 19], { L: lantern }, [
    ["L  ",
     "  L"],
  ]);
}

